import { describe, expect, it } from "vitest";
import { getAllowanceState } from "@/lib/usage/getAllowanceState";

describe("allowance presentation states", () => {
  it.each([
    [{ remaining: 3, total: 3, queued: 0 }, "healthy"],
    [{ remaining: 1, total: 3, queued: 0 }, "healthy"],
    [{ remaining: 2, total: 15, queued: 0 }, "low"],
    [{ remaining: 1, total: 5, queued: 0 }, "low"],
    [{ remaining: 0, total: 15, queued: 0 }, "empty"],
    [{ remaining: 0, total: 15, queued: 3 }, "reserved"],
    [{ remaining: 0, total: 0, queued: 0 }, "empty"],
    [{ remaining: 0, total: 0, queued: 3 }, "empty"],
    [{ remaining: 0, total: 3, queued: 8 }, "reserved"],
  ] as const)("classifies %j as %s", (values, expected) => {
    expect(getAllowanceState(values)).toBe(expected);
  });
});
